<script setup lang="ts">import { ref } from 'vue';import { useRouter,useRoute } from 'vue-router';import { useAuthStore } from '../stores/auth';const username=ref('');const password=ref('');const error=ref('');const loading=ref(false);const auth=useAuthStore();const router=useRouter();const route=useRoute();async function submit(){error.value='';loading.value=true;try{await auth.login(username.value,password.value);await router.replace(String(route.query.redirect||'/activities'))}catch{error.value='用户名或密码不正确'}finally{loading.value=false}}</script>
<template><section class="auth-page"><div class="auth-panel"><h1>欢迎回到 VolunteerFlow</h1><p>登录后查看组织中的志愿活动。</p><form @submit.prevent="submit"><label>用户名<input v-model.trim="username" required autocomplete="username"/></label><label>密码<input v-model="password" type="password" required autocomplete="current-password"/></label><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="loading">{{loading?'正在登录…':'登录'}}</button></form><RouterLink to="/register">还没有账号？创建账号</RouterLink></div></section></template>
